"""Generic tools (spec "Tools"). S2: drills, generated by rule from config/tools.toml."""

from __future__ import annotations

from dataclasses import dataclass

from . import settings
from .units import MM_PER_IN


@dataclass(frozen=True)
class Drill:
    diameter_mm: float
    label: str  # "17/64 in" style is built by the caller; this is "6.5 mm" or "0.2656 in"
    metric: bool


def _steps(start: float, stop: float, step: float) -> list[float]:
    n = round((stop - start) / step)
    return [round(start + i * step, 6) for i in range(n + 1)]


def drills(units_in_file: str) -> list[Drill]:
    """The drill set for a part: metric drills for mm files, 1/64 in drills otherwise (spec Tools)."""
    cfg = settings.tools_config()["drills"]
    if units_in_file == "mm":
        sizes = [d for r in cfg["mm"] for d in _steps(r["from_mm"], r["to_mm"], r["step_mm"])]
        return [Drill(d, f"{d:g} mm", True) for d in sizes]
    sizes = [d for r in cfg["inch"] for d in _steps(r["from_in"], r["to_in"], r["step_in"])]
    return [Drill(d * MM_PER_IN, f"{d:.4f} in", False) for d in sizes]


def match_tolerance_mm() -> float:
    return settings.tools_config()["drills"]["match_tolerance_in"] * MM_PER_IN


def nearest_drill(diameter_mm: float, units_in_file: str) -> Drill:
    """The closest drill; a tie (to 1e-6 mm) goes to the smaller drill."""
    return min(drills(units_in_file), key=lambda d: (round(abs(d.diameter_mm - diameter_mm), 6), d.diameter_mm))


def drill_range_mm(units_in_file: str) -> tuple[float, float]:
    sizes = [d.diameter_mm for d in drills(units_in_file)]
    return min(sizes), max(sizes)
